/* Scoped persona prototype. No inference, network calls, or changes to existing drafts. */
(()=>{
const key='workbench-persona-v1';
const defaults={material:'',goal:'未说明',answer:'',strength:'',issue:'',action:'',priority:'',question:'',revision:'',recheck:''};
let data={...defaults}, storageOK=true, tab='mine';
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&typeof saved==='object'&&!Array.isArray(saved))data={...defaults,...saved}}catch(e){storageOK=false}
const criteria=[
 ['social','社会身份是否清楚','除了职业，你是怎样的人？从社会关系、性格与行为中找线索，不要求公开家庭隐私。','木子·双身份定义；D1 3:48:28–3:48:48'],
 ['business','商业身份是否清楚','有商业目标时，说明以什么身份提供什么帮助。过去的职业不自动等于现在的服务；没有商业目标可以暂不适用。','木子·双身份定义；“暂不适用”为产品处理规则'],
 ['detail','特点有没有具体支撑','“专业、独立、真诚”只是起点。找真实经历、选择和行为，不替用户编故事。','李老师·标签与记忆点；真实材料优先为工作台边界'],
 ['memory','有没有可持续呈现的记忆点','检查哪些特点能在不同内容里自然呈现，不硬造反差、口头禅，不保证观众一定记住。','李老师·反复呈现细节；day1_9 23:03–23:55']
];
const sample='我40岁，做了15年HR，也是一个妈妈。我独立、专业、真诚，想分享职场经验。';
function persist(){try{localStorage.setItem(key,JSON.stringify(data));storageOK=true}catch(e){storageOK=false}const s=document.getElementById('persona-save');if(s)s.textContent=storageOK?'已保存在此浏览器；不会跨设备同步。':'本地保存不可用，请导出材料，避免丢失。'}
function input(k,title,placeholder=''){return `<label for="persona-${k}">${title}</label><textarea id="persona-${k}" data-persona="${k}" placeholder="${placeholder}">${esc(data[k]||'')}</textarea>`}
function reference(){return `<details class="source"><summary>判断依据与适用边界</summary><p>这是跨来源转化的四个检查项，不是老师原版评分表。不计算总分，不预测流量和变现，不强求每条视频同时展示两种身份。</p><p>木子：社会身份与商业身份。库内路径：工作区/拆解/拆解包/木子_方法证据_1006/02_木子方法卡.md · 卡8；采用定义段，不采用存在歧义的流量归因表述。</p><p>李老师：标签与记忆点、通过反复呈现细节建立人设。库内路径：工作区/拆解/拆解包/don课_广州26.06/提炼笔记/day1_part3.md · 论点H。讲者是Don课程嘉宾李老师，不是Don。</p><p>来源核验：本轮回读方法卡与提炼笔记，未重新听原声。采用状态：诊断方向经融新同意，本版交互待验收。应用验证：尚未完成真实用户测试。知识库未实时连接。</p></details>`}
function exampleView(){return `<div class="notice">虚构输入 · 预写结果示例。以下内容与“我的材料”无关，不是AI分析结果。</div><blockquote>${sample}</blockquote><div class="persona-results"><section><span class="eyebrow">值得保留</span><h3>职业经历清楚，社会身份有线索</h3><p>“15年HR”说明职业背景；“妈妈”提供社会身份线索。可以保留，但不意味着必须做亲子内容，也不能据此认定专业能力已被证明。</p></section><section><span class="eyebrow">优先补充</span><h3>把自我评价变成具体事情</h3><p>“独立、专业、真诚”目前没有经历支撑。不是认定这些特点不成立，而是现有材料还无法让人看见。</p><p><strong>先回答一个问题：</strong>做HR时，有哪件事需要你作出判断或选择？当时发生了什么，你怎么做，结果怎样？</p></section><section><span class="eyebrow">暂不能判断</span><h3>商业身份与稳定记忆点</h3><p>没有商业目标或服务材料，不能替你决定卖职业咨询。没有连续内容或更多经历，也不能断言某个特点已经形成观众记忆。</p></section></div><p class="small">反馈顺序：保留什么 → 问题在哪 → 为什么 → 怎么补 → 先做什么。缺材料不等于做得差。</p>${reference()}`}
function mineView(){const history=['strength','issue','action','priority','question','recheck'].some(k=>data[k])||criteria.some(([k])=>data[k]);return `<div class="steps"><span class="current">1 提供材料</span><span>2 AI追问</span><span>3 诊断与修改建议</span><span>4 修改后复查</span></div><p>你只需讲自己的情况，判断与建议应由AI完成；你决定是否接受。</p>${input('material','先介绍一下你自己','粘贴已有介绍，或说说你做过什么、想做什么账号。没有整理好的材料也可以。')}<label for="persona-goal">目前有没有商业目标？（可暂不确定）</label><select id="persona-goal" data-persona="goal">${['未说明','暂时没有','有，写在材料中'].map(x=>`<option ${data.goal===x?'selected':''}>${x}</option>`).join('')}</select><div class="actions"><button id="persona-import">带入已有定位材料</button><button id="persona-export">导出材料</button></div><p id="persona-save" class="small" role="status">${storageOK?'仅保存在此浏览器，尚未发送给模型。':'本地保存不可用，请导出材料。'}</p><div class="notice" id="persona-service"><strong>自动分析尚未开放</strong><p>当前站点未连接模型服务，不能分析你的材料。站点负责人需先确定服务及费用，再开通。不会让你自己填写判断，也不会用示例代替结果。</p></div><details class="persona-notes"><summary>还有想补充的事实？（选填）</summary>${input('answer','补充材料','只补充你认为重要的真实情况，不必自己分析问题。')}</details><details class="persona-notes"><summary>AI将依据哪些方面分析？</summary>${criteria.map(([id,title,desc,source])=>`<div class="row"><h3>${title}</h3><p>${desc}</p><small>依据：${source}</small></div>`).join('')}<p>材料不足时先追问；只对有依据的部分作判断，不给虚假的总分。</p></details>${history?`<details class="persona-notes"><summary>查看旧版保存的记录（仅保留，不是AI结论）</summary><pre style="white-space:pre-wrap">${esc(exportText())}</pre></details>`:''}${reference()}`}
function exportText(){return '# 人设定位材料与人工审阅记录\n\n交互原型，未接入AI；状态与意见均为人工填写，未评不等于通过。\n\n'+[['material','原始材料'],['goal','商业目标'],['strength','值得保留'],['issue','问题与缺口'],['action','修改建议'],['priority','优先动作'],['question','追问'],['answer','补充材料'],['revision','修改后材料'],['recheck','复查记录']].map(([k,t])=>'## '+t+'\n'+(data[k]||'未填写')).join('\n\n')+'\n\n## 四项人工状态\n'+criteria.map(([id,t])=>'- '+t+'：'+(data[id]||'未评')).join('\n')+'\n\n依据：木子方法卡·卡8；Don课程嘉宾李老师 day1_part3·论点H。四项为产品整理，未在真实用户中验证。';}
function mount(){if(page!=='position')return;const box=document.createElement('section');box.className='panel persona-module';box.id='persona-module';box.innerHTML=`<div class="eyebrow">人设定位 / AI服务待接入</div><h2>你给材料，AI负责分析</h2><div class="actions" role="group" aria-label="人设定位视图"><button id="persona-mine" aria-pressed="${tab==='mine'}">我的材料</button><button id="persona-example" aria-pressed="${tab==='example'}">查看输出格式示例（非分析结果）</button></div><div id="persona-body">${tab==='mine'?mineView():exampleView()}</div>`;const grid=app.querySelector('.position-grid');app.insertBefore(box,grid);const old=document.createElement('details');old.className='persona-notes';old.innerHTML='<summary>旧版定位底稿（选填，已有内容保留）</summary>';grid.before(old);old.appendChild(grid);const notice=app.querySelector(':scope > .notice');if(notice)notice.remove();box.querySelectorAll('[data-persona]').forEach(el=>el.addEventListener('input',()=>{data[el.dataset.persona]=el.value;persist()}));box.querySelector('#persona-mine').onclick=()=>{tab='mine';render()};box.querySelector('#persona-example').onclick=()=>{tab='example';render()};if(tab==='mine'){box.querySelector('#persona-export').onclick=()=>download('人设定位_材料与历史记录.md',exportText());box.querySelector('#persona-import').onclick=()=>{const text=[['社会身份',state.socialIdentity],['商业身份',state.businessIdentity],['真实细节',state.identityEvidence]].filter(x=>x[1]&&x[1].trim()).map(x=>x[0]+'：'+x[1]).join('\n');if(!text){box.querySelector('#persona-save').textContent='旧版底稿还没有材料；可直接在本区输入。';return}if(data.material.includes(text)){box.querySelector('#persona-save').textContent='这些定位字段已带入，未重复追加。';return}data.material+=(data.material?'\n\n':'')+text;persist();render()}}}
const previousRender=render;render=function(){previousRender();mount()};
const style=document.createElement('style');style.textContent='.persona-module{margin-bottom:24px}.persona-module button[aria-pressed="true"]{background:var(--green);color:white}.persona-module textarea{min-height:95px}.persona-module blockquote{margin:20px 0;padding:18px;border-left:3px solid var(--purple);background:var(--light)}.persona-results{display:grid;gap:16px}.persona-results section,.persona-criterion{padding:18px 0;border-bottom:1px solid var(--line)}.persona-criterion{display:grid;grid-template-columns:minmax(0,1fr) 180px;gap:20px}.persona-criterion small{color:var(--muted)}.persona-notes{margin:20px 0;padding:16px;border:1px solid var(--line);border-radius:10px}.persona-notes summary{cursor:pointer;font-weight:600}.persona-module .actions{flex-wrap:wrap}.persona-module{overflow-wrap:anywhere}@media(max-width:650px){.persona-criterion{grid-template-columns:1fr}}';document.head.appendChild(style);render();
})();
